const key='ahs-settlement-v1';
let state={seed:1,day:1,villages:[],roads:[],shipments:[],speed:1},mode='inspect',role='rice',roadStart=null,chosen=null,last=performance.now();
try{let v=JSON.parse(localStorage.getItem(key));if(v&&Array.isArray(v.villages)&&Array.isArray(v.roads)&&Array.isArray(v.shipments)){state=v;seed=v.seed}}catch(e){}
const names=['Trowulan','Janggala','Kediri','Tumapel','Daha','Singhasari','Mataram','Kahuripan'];
