function msg(t){document.querySelector('#message').textContent=t}
function roadPoint(x,z){return [x+.5,height(x+.5,z+.5)+.08,z+.5]}
function drawRoads(){for(const r of state.roads){for(let i=1;i<r.path.length;i++){let [ax,az]=r.path[i-1],[bx,bz]=r.path[i],a=roadPoint(ax,az),b=roadPoint(bx,bz),dx=b[0]-a[0],dz=b[2]-a[2],l=Math.hypot(dx,dz)||1,px=-dz/l*.18,pz=dx/l*.18;quad([a[0]+px,a[1],a[2]+pz],[a[0]-px,a[1],a[2]-pz],[b[0]-px,b[1],b[2]-pz],[b[0]+px,b[1],b[2]+pz],[.65,.51,.34])}}}
function drawSettlements(){for(const v of state.villages){let list=[{kind:'house',x:v.x-2,z:v.z-1,w:2,d:2},{kind:'house',x:v.x+2,z:v.z-2,w:2,d:2},{kind:v.role,x:v.x+1,z:v.z+2,w:v.role==='rice'?4:2,d:v.role==='rice'?4:2}];AssetStudy.build(tri,quad,list);let y=height(v.x,v.z)+.1;quad([v.x-.55,y,v.z-.55],[v.x+.55,y,v.z-.55],[v.x+.55,y,v.z+.55],[v.x-.55,y,v.z+.55],[.93,.73,.28])}}
function findVillage(x,z){let best=null,dis=Infinity;for(const v of state.villages){let d=Math.hypot(v.x-(x+.5),v.z-(z+.5));if(d<4&&d<dis){best=v;dis=d}}return best}
function details(){let el=document.querySelector('#details'),v=state.villages.find(v=>v.id===chosen);if(!v){el.innerHTML='<p>Klik sebuah desa di peta untuk melihat stok dan statusnya.</p>';return}let connected=state.roads.filter(r=>r.a===v.id||r.b===v.id).length,waiting=state.shipments.filter(t=>t.to===v.id);el.innerHTML=`<h3>${v.name}</h3><p>Spesialisasi: <b>${v.role==='rice'?'Sawah / pangan':'Penebangan / kayu'}</b><br>Penduduk: 4 · Terhubung: ${connected} jalan</p><div class="stock"><span>🌾 Pangan <b>${Math.floor(v.food)} / 70</b></span><span>🪵 Kayu <b>${Math.floor(v.wood)} / ${VillageSimulation.capacity(v,'wood')}</b></span></div><p>Produksi / hari: ${v.role==='rice'?'+10 pangan':'+5 kayu'}<br>Konsumsi / hari: −${v.role==='rice'?2:1} pangan<br>Target cadangan pangan: ${v.role==='rice'?50:30}<br>${v.role==='rice'?'Batas pengiriman pangan: '+(v.food>=50?'8':'2')+' / hari<br>Produksi pangan: '+(v.foodPaused?'berhenti sementara':'aktif'):'Batas pengiriman kayu: 1 / hari'}</p><p>${v.food>70||v.wood>VillageSimulation.capacity(v,'wood')?'⚠ Stok dari permainan lama di atas kapasitas; produksi berhenti sampai tersedia ruang.':''}</p><p>${waiting.length?'Dalam perjalanan: '+waiting.map(t=>`${t.amount} ${t.good==='food'?'pangan':'kayu'} (${t.days} hari)`).join(', '):'Tidak ada barang dalam perjalanan.'}</p><p>${v.food<3?'⚠ Pangan hampir habis.':connected?'✓ Terhubung dengan jaringan jalan.':'⚠ Belum terhubung ke desa lain.'}</p>`}
function update(){let food=state.villages.reduce((n,v)=>n+v.food,0),wood=state.villages.reduce((n,v)=>n+v.wood,0);document.querySelector('#resources').innerHTML=`<div><span>HARI</span><strong>${state.day}</strong></div><div><span>🏘 DESA</span><strong>${state.villages.length}</strong></div><div><span>🌾 PANGAN TOTAL</span><strong>${Math.floor(food)}</strong></div><div><span>🪵 KAYU TOTAL</span><strong>${Math.floor(wood)}</strong></div>`;document.querySelector('#speed').textContent=state.speed?'❚❚ Jeda':'▶ Lanjut';document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));document.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('active',b.dataset.role===role));document.querySelector('#transport').textContent=state.shipments.length?state.shipments.map(t=>{let a=state.villages.find(v=>v.id===t.from),b=state.villages.find(v=>v.id===t.to);return `${a.name} → ${b.name}: ${t.amount} ${t.good==='food'?'pangan':'kayu'} (${t.days} hari)`}).join(' · '):'Belum ada barang dalam perjalanan.';details()}
