window.gamePlace=(x,z)=>{let v=findVillage(x,z);if(mode==='inspect'){chosen=v?.id||null;update();msg(v?`${v.name} dipilih.`:'Klik lebih dekat ke pusat desa.');return true}if(mode==='road'){if(!v){msg('Klik pusat desa (kotak kuning).');return true}if(!roadStart){roadStart=v.id;chosen=v.id;msg(`${v.name} dipilih. Klik pusat desa tujuan.`);update();return true}if(roadStart===v.id){msg('Pilih desa kedua yang berbeda.');return true}let a=state.villages.find(s=>s.id===roadStart);if(state.roads.some(r=>r.a===a.id&&r.b===v.id||r.b===a.id&&r.a===v.id)){msg('Kedua desa sudah terhubung langsung.');roadStart=null;return true}let path=nearestPath(a,v);if(!path){msg('Jalan tidak dapat melewati sungai atau bukit. Pilih lokasi lain.');roadStart=null;return true}state.roads.push({a:a.id,b:v.id,path});roadStart=null;save();generate();update();msg(`Jalan ${a.name}–${v.name} selesai. Distribusi otomatis dimulai saat ada kebutuhan dan surplus.`);return true}let cx=x+.5,cz=z+.5;if(x < -56||x>56||z< -56||z>56){msg('Terlalu dekat tepi peta.');return true}if(state.villages.some(v=>Math.hypot(v.x-cx,v.z-cz)<12)){msg('Area settlement bertumpuk. Pilih lokasi yang lebih jauh.');return true}for(let dx=-4;dx<=4;dx++)for(let dz=-4;dz<=4;dz++){let t=map.typeAt(cx+dx,cz+dz);if(t===MapGenerator.WATER||t===MapGenerator.HILL){msg('Area desa mengenai air atau bukit. Pilih dataran yang lebih luas.');return true}}let id='v'+Date.now(),newVillage={id,name:names[state.villages.length%names.length]+' '+(Math.floor(state.villages.length/names.length)||''),x:cx,z:cz,role,food:12,wood:4};state.villages.push(newVillage);chosen=id;save();generate();update();msg(`${newVillage.name} didirikan! Pilih desa lain atau hubungkan jalan.`);return true};
