canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'&&e.button!==0&&e.button!==2)return;e.preventDefault();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,rotate:e.pointerType!=='touch'&&e.button===2});if(pointers.size===1)tapEligible=e.button===0;else tapEligible=false;canvas.setPointerCapture(e.pointerId);beginGesture()});
